import { PostHuntDetails } from "@hunt/puzzle-components";
import { TextInput } from "@hunt/styled-ui";
import React, { useState } from "react";

const LocalAnswerChecker = ({ answer }: { answer: string }) => {
  const [value, setValue] = useState("");
  const [result, setResult] = useState<"correct" | "incorrect" | null>(null);

  const check = () => {
    const normalize = (s: string) => s.toUpperCase().replace(/\s/g, "");
    const normalized = normalize(value);
    const normalizedAnswer = normalize(answer);
    if (normalized === normalizedAnswer) {
      setResult("correct");
    } else {
      setResult("incorrect");
    }
  };

  return (
    <div className="my-4">
      <div className="flex items-center gap-2">
        <TextInput
          value={value}
          onChange={(e) => {
            setValue(e.target.value);
            setResult(null);
          }}
          placeholder="Enter answer"
          className="flex-grow"
        />
        <button
          type="button"
          onClick={check}
          className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600"
        >
          Check
        </button>
      </div>
      {result === "correct" && (
        <div className="text-green-600 font-bold mt-2">Correct</div>
      )}
      {result === "incorrect" && (
        <div className="text-red-600 font-bold mt-2">Incorrect</div>
      )}
    </div>
  );
};

